package com.vandorlabs.neoforge.navigation.observer;
import java.lang.reflect.*;import java.util.*;import com.mojang.blaze3d.vertex.*;import com.vandorlabs.neoforge.navigation.observer.client.NativeObserverRenderer;import com.vandorlabs.neoforge.builders.client.NativeBuilderModel;import com.vandorlabs.navigation.ObserverScale;import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.phys.AABB;
/** Actual renderer emission for every supported width; immutable mesh reuse and scaled geographic anchors. */
public final class NativeObserverScaleRenderChecks {
 private static int checks;private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 @SuppressWarnings("unchecked") public static void run(){try{var mc=Minecraft.getInstance();var field=NativeObserverRenderer.class.getDeclaredField("MESHES");field.setAccessible(true);var meshes=(Map<String,NativeBuilderModel>)field.get(null);need(meshes.size()==3,"fixed cached observer mesh count");int draws=0;for(var base:NativeObserverDesigns.ALL)for(int width=base.width();width<=ObserverScale.maximumWidth(base.id());width++)for(boolean inverted:new boolean[]{false,true})for(var facing:new Direction[]{Direction.NORTH,Direction.EAST,Direction.SOUTH,Direction.WEST}){
 var state=NativeObserverBindings.CORES.get(base.id()).defaultBlockState().setValue(NativeObserverCoreBlock.FORMED,true).setValue(NativeObserverCoreBlock.FACING,facing);var t=new NativeObserverEntity(BlockPos.ZERO,state);t.setLevel(mc.level);var raw=new CompoundTag();raw.putUUID("ObserverKey",new UUID(1,2));raw.putInt("ObserverWidth",width);raw.putBoolean("ObserverInverted",inverted);t.loadWithComponents(raw,mc.level.registryAccess());need(!t.inert(),"render source typed width accepted");var d=t.design();var expected=new AABB(t.cell(0,0,0)).minmax(new AABB(t.cell(d.width()-1,d.height()-1,d.depth()-1))).inflate(.126*ObserverScale.linearScale(d.id(),width));int[] vertices={0},inletVertices={0};
 var target=(VertexConsumer)Proxy.newProxyInstance(VertexConsumer.class.getClassLoader(),new Class<?>[]{VertexConsumer.class},(proxy,method,args)->{if(method.getName().equals("addVertex")&&args!=null&&args.length==3&&args[0] instanceof Float){double x=(Float)args[0],y=(Float)args[1],z=(Float)args[2];need(Double.isFinite(x)&&Double.isFinite(y)&&Double.isFinite(z),"finite scaled observer vertices");need(x>=expected.minX&&x<=expected.maxX&&y>=expected.minY&&y<=expected.maxY&&z>=expected.minZ&&z<=expected.maxZ,"scaled observer remains anchored to actual frame "+d.id()+"/"+d.width()+"/"+facing+"/"+inverted+" vertex="+x+","+y+","+z+" bounds="+expected);vertices[0]++;}else if(method.getName().equals("addVertex")&&args!=null&&args.length==4&&args[0] instanceof PoseStack.Pose){float y=(Float)args[2];need(Math.abs(y-(inverted?1-d.height():0)+.0005F)<1e-5,"downward inlet rendered on physical underside");inletVertices[0]++;}return method.getReturnType()==VertexConsumer.class?proxy:null;});
 new NativeObserverRenderer(null).render(t,0,new PoseStack(),layer->target,0xf000f0,0);int count=d.id().equals("standalone_dish")?meshes.get("standalone_dish/scanning/parts/static").vertexCount()+meshes.get("standalone_dish/scanning/parts/rotor").vertexCount():meshes.get("standalone_antenna/scanning/complete").vertexCount();need(vertices[0]==count&&count>0&&inletVertices[0]==4,"all cached static/rotor vertices emitted once");draws++;
 }System.out.println("[vandorlabs][navigation-client] observer-scale PASS checks="+checks+" draws="+draws+" widths/upright/inverted/facings/cachedMeshes/physicalBounds");}catch(ReflectiveOperationException error){throw new AssertionError(error);}}
 private NativeObserverScaleRenderChecks(){}
}
